+        static final int HEADER_LENGTH = 4;
+        private static final byte[] DEFLATE_HEADER = new byte[]{'D', 'F', 'L', '\0'};
+        private static final byte[] LZ4_HEADER = new byte[]{'L', 'Z', '4', '\0'};
+        private static final int LZ4_BLOCK_SIZE;
+
