+                if (lz4BlockSize < 1024 || lz4BlockSize > (512 * 1024)) {
+                    throw new IllegalArgumentException("lz4_block_size must be >= 1KB and <= 512KB");
+                }
+                LZ4_BLOCK_SIZE = lz4BlockSize;
+            } else {
+                LZ4_BLOCK_SIZE = 64 * 1024;
+            }
+        }
